import {workingSets,volume,bestFor,previousEntries,toDisplay,activityDays} from './core.mjs';
import {appearanceControls,ratingBadge} from './preferences.mjs';
export const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const num=n=>new Intl.NumberFormat(undefined,{maximumFractionDigits:1}).format(n);
export const date=v=>new Date(v).toLocaleDateString(undefined,{day:'numeric',month:'short'});
export const longdate=v=>new Date(v).toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long'});
export const duration=w=>Math.max(0,Math.round((Date.parse(w.ended||new Date().toISOString())-Date.parse(w.started))/60000));
const metric=(value,label)=>`<div class="metric"><strong>${value}</strong><span>${label}</span></div>`;
export function createViews(state,period,selectedExercise,offlineReady,routineFilter='All',historyFilter='All'){
const unit=state.settings.unit,weight=n=>num(toDisplay(n,unit)),ex=id=>state.exercises.find(e=>e.id===id);
function calendar(count=112){const days=activityDays(state,count),trained=days.filter(d=>d.status==='trained').length,missed=days.filter(d=>d.status==='missed').length;return `<div class="section-heading"><h2>Show up. Stack days.</h2><span class="muted">Last ${count/7} weeks</span></div><div class="calendar-panel"><div class="calendar-months"><span>${date(days[0].date+'T12:00:00')}</span><span>${date(days.at(-1).date+'T12:00:00')}</span></div><div class="calendar" role="group" aria-label="Training activity for the last ${count/7} weeks">${days.map(d=>`<button class="day ${d.status} intensity-${d.level}" data-day="${d.date}" aria-label="${d.date}: ${d.status==='trained'?d.count+' workout'+(d.count===1?'':'s')+', '+d.minutes+' minutes':d.status==='missed'?'Missed planned session':d.status==='planned'?'Planned for today':'Rest or unplanned day'}" title="${d.date}: ${d.status}${d.count ? ` · ${d.minutes} min` : ''}" ${d.status==='future'?'disabled':''}></button>`).join('')}</div><div class="calendar-legend"><span><i class="intensity-1"></i> &lt;30m</span><span><i class="intensity-2"></i> 30–59m</span><span><i class="intensity-3"></i> 60–89m</span><span><i class="intensity-4"></i> 90m+</span><span><i class="missed"></i> Missed</span><span><i class="rest"></i> Rest</span><span><i class="planned"></i> Today’s plan</span></div><p class="muted" style="font-size:.85rem;margin:18px 0 0">${trained} days trained${state.settings.schedule.length?' · '+missed+' planned days missed':' · Choose training days to track missed sessions.'}</p><button class="text-link" data-action="schedule">${state.settings.schedule.length?'Edit training days':'Set training days'} ↗</button></div>`}
function home(){const week=state.workouts.filter(w=>Date.parse(w.started)>Date.now()-7*864e5);return `<p class="eyebrow">${esc(new Date().toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long'}).toUpperCase())}</p><h1>Ready when<br>you are.</h1><p class="muted">A little stronger, one session at a time.</p><button class="primary wide" data-action="start">＋ Start an empty workout</button><div class="metrics">${metric(week.length,'sessions · last 7 days')}${metric(week.reduce((n,w)=>n+workingSets(w).length,0),'working sets')}${metric(num(week.reduce((n,w)=>n+duration(w),0)),'minutes trained')}</div><div class="section-heading"><h2>Your routines</h2><button class="text-link" data-action="new-routine">＋ New routine</button></div><div class="chips routine-filters" aria-label="Filter routines by muscle group">${['All',...new Set(state.routines.flatMap(r=>r.items.map(e=>ex(e.exerciseId)?.muscle||'Other')))].map(g=>`<button data-routine-filter="${esc(g)}" aria-pressed="${routineFilter===g}" class="${routineFilter===g?'active':''}">${esc(g)}</button>`).join('')}</div><div class="routine-cards">${state.routines.filter(r=>routineFilter==='All'||r.items.some(e=>(ex(e.exerciseId)?.muscle||'Other')===routineFilter)).map(r=>`<article class="routine-card"><div class="row between"><h3>${esc(r.name)}</h3><button class="quiet" data-edit-routine="${r.id}" aria-label="Edit ${esc(r.name)} routine">Edit ↗</button></div><div class="muscle-tags">${[...new Set(r.items.map(e=>ex(e.exerciseId)?.muscle||'Other'))].map(g=>`<span>${esc(g)}</span>`).join('')}</div><p class="muted">${r.items.length} exercises · ${r.items.reduce((n,e)=>n+e.sets.length,0)} sets</p><button class="secondary wide" data-routine="${r.id}" aria-label="Start ${esc(r.name)} routine">Start routine ↗</button></article>`).join('')||'<p class="empty">No routines here yet. Create one with your favorite exercises.</p>'}</div>${calendar()}<div class="install-tip"><p class="muted">Keep Setline on your Home Screen.</p><button class="text-link" data-action="install">How to install ↗</button></div>`}
function exercise(e){const exercise=ex(e.exerciseId),prev=previousEntries(state.workouts,e.exerciseId)[0];const last=prev?.entries.filter(x=>x.exerciseId===e.exerciseId).flatMap(x=>x.sets).filter(s=>s.done&&s.type==='normal');const group=e.group?state.draft.entries.filter(x=>x.group===e.group&&x.id!==e.id).map(x=>ex(x.exerciseId).name):[];return `<section class="exercise" data-entry="${e.id}"><div class="exercise-title"><div class="grow"><p class="eyebrow" style="margin-bottom:4px">${esc(exercise.muscle)}${e.group?' · SUPERSET':''}</p><h3>${esc(exercise.name)}</h3><button class="text-link" data-history-ex="${exercise.id}">${last?.length?'Last: '+last.map(s=>`${weight(s.weight)} × ${s.reps}`).join(' / '):'View exercise history'} ↗</button></div><button class="quiet" data-entry-options="${e.id}" aria-label="Options for ${esc(exercise.name)}">•••</button></div>${group.length?`<p class="note" style="margin:10px 0">Superset with ${esc(group.join(' + '))}</p>`:''}<div class="set-grid set-head"><span>SET</span><span>${unit.toUpperCase()}</span><span>REPS</span><span>DONE</span><span></span></div>${e.sets.map((s,j)=>`<div class="set-grid set-row ${s.done?'complete':''}"><button class="set-type" data-set-type="${e.id}/${s.id}" aria-label="Set ${j+1} type: ${s.type}">${s.type==='warmup'?'W':s.type==='drop'?'D':j+1}</button><input type="number" inputmode="decimal" min="0" step="any" max="22046" aria-label="${esc(exercise.name)} set ${j+1} weight in ${unit}" data-set="${e.id}/${s.id}/weight" value="${toDisplay(s.weight,unit)}" placeholder="—"><input type="number" inputmode="numeric" min="1" max="1000" step="1" aria-label="${esc(exercise.name)} set ${j+1} reps" data-set="${e.id}/${s.id}/reps" value="${s.reps??''}" placeholder="—"><button class="check" data-complete="${e.id}/${s.id}" aria-label="${s.done?'Uncheck':'Complete'} ${esc(exercise.name)} set ${j+1}" aria-pressed="${s.done}">✓</button><button class="remove" data-remove-set="${e.id}/${s.id}" aria-label="Remove ${esc(exercise.name)} set ${j+1}">×</button></div>`).join('')}<div class="exercise-actions"><button class="text-link" data-add-set="${e.id}">＋ Add set</button><button class="text-link" data-drop="${e.id}">＋ Drop set</button><button class="quiet" data-pair="${e.id}">${e.group?'Edit superset':'Superset'}</button></div></section>`}
function workout(){const w=state.draft;if(!w)return home();return `<div id="rest-timer" class="timer hidden"><span>Rest <strong id="rest-count"></strong></span><div class="row"><button data-action="rest-plus">+30s</button><button data-action="rest-skip">Skip</button></div></div><div class="row between"><p class="eyebrow" style="margin:0">WORKOUT IN PROGRESS</p><span class="badge"><span id="elapsed">${duration(w)} min</span></span></div><input class="session-name" aria-label="Workout name" value="${esc(w.name)}" maxlength="120" data-field="name"><div class="row muted" style="font-size:.875rem;margin:8px 0 22px"><span>${w.entries.flatMap(e=>e.sets).filter(s=>s.done).length} sets complete</span><span>·</span><span>${weight(volume(w))} ${unit} volume</span></div>${w.entries.map(exercise).join('')}${!w.entries.length?'<div class="empty"><h2>Your session starts here.</h2><p>Add an exercise and log your first set.</p></div>':''}<button class="secondary wide" data-action="add-exercise">＋ Add exercise</button><label class="muted" style="display:block;margin:24px 0 8px" for="session-notes">Session notes</label><textarea id="session-notes" rows="2" maxlength="10000" placeholder="How did it feel?" data-field="notes">${esc(w.notes)}</textarea><div class="session-footer"><button class="secondary" data-action="save-routine">Save as routine</button><button class="primary" data-action="finish">Finish workout ↗</button></div><details class="in-session-routines"><summary>Manage routines</summary><button class="text-link" data-action="new-routine">＋ New routine</button>${state.routines.map(r=>`<button class="routine-edit-row" data-edit-routine="${r.id}">${esc(r.name)} <span>Edit ↗</span></button>`).join('')}</details><button class="quiet danger wide" data-action="discard">Discard workout</button>`}
function history(){const ws=[...state.workouts].filter(w=>historyFilter==='All'||w.entries.some(e=>(ex(e.exerciseId)?.muscle||'Other')===historyFilter)).sort((a,b)=>Date.parse(b.started)-Date.parse(a.started));return `<p class="eyebrow">THE WORK YOU PUT IN</p><h1>History</h1><p class="muted">${ws.length} ${historyFilter==='All'?'saved':'matching'} ${ws.length===1?'session':'sessions'}</p>${state.workouts.length?`<div class="chips routine-filters" aria-label="Filter history by muscle group">${['All',...new Set(state.workouts.flatMap(w=>w.entries.map(e=>ex(e.exerciseId)?.muscle||'Other')))].map(g=>`<button data-history-filter="${esc(g)}" aria-pressed="${historyFilter===g}" class="${historyFilter===g?'active':''}">${esc(g)}</button>`).join('')}</div>`:''}${!ws.length&&state.workouts.length?'<p class="empty">No sessions for this muscle group yet. Choose another group above.</p>':ws.length?ws.map(w=>`<button class="history-item" data-workout="${w.id}"><div class="history-date">${esc(longdate(w.started))}</div><div class="row between"><div><h3>${esc(w.name)}</h3><small>${w.entries.length} exercises · ${workingSets(w).length} sets · ${duration(w)} min</small>${ratingBadge(w.rating)}</div><span class="history-volume">${weight(volume(w))}<small> ${unit}</small></span></div></button>`).join(''):'<div class="empty"><h2>Your first session belongs here.</h2><p>Finish a workout to start building your history.</p><button class="secondary" data-nav="workout">Start training</button></div>'}`}
function chart(id,cutoff){const points=[...state.workouts].sort((a,b)=>Date.parse(a.started)-Date.parse(b.started)).filter(w=>Date.parse(w.started)>=cutoff).map(w=>({w,s:w.entries.filter(e=>e.exerciseId===id).flatMap(e=>e.sets.filter(s=>s.done&&s.type==='normal'))})).filter(x=>x.s.length).map(x=>({v:Math.max(...x.s.map(s=>s.weight)),date:x.w.started}));if(!points.length)return '<p class="empty">No normal working sets in this period.</p>';const max=Math.max(...points.map(p=>p.v),1)*1.12;const coords=points.map((p,i)=>({x:points.length===1?280:28+i/(points.length-1)*504,y:140-p.v/max*120,...p}));return `<svg class="chart" viewBox="0 0 560 180" role="img" aria-label="Heaviest weight over ${points.length} sessions. First ${weight(points[0].v)}, latest ${weight(points.at(-1).v)} ${unit}."><path d="M28 140H532 M28 80H532 M28 20H532" fill="none" stroke="var(--line)" stroke-dasharray="3 6"/><polyline points="${coords.map(p=>p.x+','+p.y).join(' ')}" fill="none" stroke="var(--accent)" stroke-width="3"/>${coords.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4" fill="var(--accent)"><title>${date(p.date)}: ${weight(p.v)} ${unit}</title></circle>`).join('')}<text x="28" y="170" class="chart-label">${date(points[0].date)}</text><text x="532" y="170" text-anchor="end" class="chart-label">${date(points.at(-1).date)}</text></svg>`}
function progress(){const cutoff=period?Date.now()-period*864e5:0,ws=state.workouts.filter(w=>Date.parse(w.started)>=cutoff);const ids=[...new Set(state.workouts.flatMap(w=>w.entries.map(e=>e.exerciseId)))];if(!ids.includes(selectedExercise))selectedExercise=ids[0]||'';const best=selectedExercise?bestFor(state.workouts,selectedExercise):null;return `<p class="eyebrow">PROOF OF PROGRESS</p><h1>Stronger over time.</h1><div class="chips" aria-label="Statistics period">${[[7,'7 days'],[30,'30 days'],[90,'90 days'],[0,'All time']].map(([v,l])=>`<button data-period="${v}" class="${period===v?'active':''}">${l}</button>`).join('')}</div><div class="metrics">${metric(ws.length,'sessions')}${metric(weight(ws.reduce((n,w)=>n+volume(w),0)),`${unit} total volume`)}${metric(ws.reduce((n,w)=>n+workingSets(w).length,0),'working sets')}</div>${calendar()}<div class="section-heading"><h2>Exercise progress</h2><span class="muted">All-time records</span></div>${ids.length?`<select aria-label="Exercise for progress" id="progress-exercise" style="width:100%;margin-bottom:22px">${ids.map(id=>`<option value="${id}" ${id===selectedExercise?'selected':''}>${esc(ex(id)?.name)}</option>`).join('')}</select><div class="panel"><p class="eyebrow">HEAVIEST WORKING SET · ${unit.toUpperCase()}</p>${chart(selectedExercise,cutoff)}<div class="metrics" style="margin-bottom:0">${metric(best.weight===null?'—':weight(best.weight),'heaviest set')}${metric(best.e1rm===null?'—':weight(best.e1rm),'estimated 1RM')}${metric(best.reps??'—','most reps')}</div></div><button class="text-link" data-history-ex="${selectedExercise}">Full exercise history ↗</button><p class="note">Records use normal working sets. Estimated 1RM uses the Epley formula for sets of 1–12 reps. Volume includes drop sets and excludes warmups; bodyweight counts as 0 added weight.</p>`:'<div class="empty"><h2>Every record starts somewhere.</h2><p>Finish a workout to see your exercise trends and personal records.</p></div>'}`}
function settings(){return `<p class="eyebrow">MAKE IT YOURS</p><h1>Your setup.</h1><div class="appearance-settings">${appearanceControls(state.settings)}</div><div class="setting"><label for="unit">Weight unit</label><select id="unit"><option value="kg" ${unit==='kg'?'selected':''}>Kilograms (kg)</option><option value="lb" ${unit==='lb'?'selected':''}>Pounds (lb)</option></select><p>Existing weights convert automatically.</p></div><div class="setting"><label for="rest">Rest timer</label><select id="rest">${[[0,'Off'],[30,'30 seconds'],[60,'1 minute'],[90,'1 min 30 sec'],[120,'2 minutes'],[180,'3 minutes'],[300,'5 minutes']].map(([n,l])=>`<option value="${n}" ${state.settings.rest===n?'selected':''}>${l}</option>`).join('')}</select><p>Starts when you complete a set. Drop sets and alternating superset exercises keep you moving. The countdown resumes after screen lock; background alerts aren’t supported.</p></div><div class="setting"><label>Training days</label><p>${state.settings.schedule.length?state.settings.schedule.map(i=>['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][i]).join(', '):'No weekly schedule set.'} Missed days are counted from ${date(state.settings.trackingSince+'T12:00:00')}. Changing your schedule applies from today.</p><button class="secondary" data-action="schedule">Choose training days</button></div><div class="setting"><label>Your data, on this device</label><p>Workouts stay in this browser or installed app. No account and no workout database online. Each friend gets their own log. Export a backup regularly: clearing website data or losing your phone can erase your history.</p><div class="row"><button class="primary" data-action="backup">Export full backup</button><button class="secondary" data-action="csv">Export CSV</button><button class="secondary" data-action="import">Restore backup</button></div><input id="import-file" type="file" accept="application/json,.json" hidden><p>${state.settings.lastBackup?'Last backup downloaded: '+longdate(state.settings.lastBackup):'No backup exported yet.'} · ${num(new Blob([JSON.stringify(state)]).size/1024)} KB stored</p><button class="text-link" data-action="persist-storage">Request persistent storage</button></div><div class="setting"><label>Install on your iPhone</label><p>Open this link in Safari, tap Share, then Add to Home Screen. If shown, keep Open as Web App enabled. ${offlineReady?'The app is ready for offline use on this device.':'Open once online and wait for the offline cache before using it without a connection.'}</p><button class="secondary" data-action="share">Share app link</button></div><div class="setting"><label>Apple Health</label><p>This web version cannot connect to Apple Health. HealthKit integration requires a native iPhone app.</p></div><p class="muted" style="font-size:.8rem;margin-top:28px">Setline 2.0 · Your training, recorded.</p>`}
return {workout,history,progress,settings};}
